	"fmt"
	"math"
	"time"

	"github.com/dop251/goja"
)

// CalculateDiscount executes a JavaScript script with the given order object
// and returns the calculated discount amount.
func CalculateDiscount(script string, order map[string]interface{}) (float64, error) {
	vm := goja.New()

	// Inject the entire order object as a single variable named "order"
	// so that scripts can access properties like order.total, order.isMember, etc.
	if err := vm.Set("order", order); err != nil {
		return 0, fmt.Errorf("failed to set order variable: %w", err)
	}

	// Set up a timeout channel to prevent infinite loops (DoS protection).
	timeout := time.After(5 * time.Second)
	done := make(chan struct{})
	var val goja.Value
	var execErr error

	go func() {
		defer close(done)
		val, execErr = vm.RunString(script)
	}()

	select {
	case <-done:
		// Execution completed normally.
	case <-timeout:
		// Execution timed out.
		vm.Interrupt("execution timeout")
		<-done // Wait for the goroutine to finish after interruption.
		return 0, fmt.Errorf("script execution timed out")
	}

	if execErr != nil {
		return 0, fmt.Errorf("script execution error: %w", execErr)
	}

	// The script should return a number (discount amount).
	if val == nil || goja.IsUndefined(val) || goja.IsNull(val) {
		return 0, fmt.Errorf("script did not return a value")
	}

	discount := val.ToFloat()

	// Basic sanity check: discount should not be NaN or Inf.
	if math.IsNaN(discount) || math.IsInf(discount, 0) {
		return 0, fmt.Errorf("invalid discount value: %v", discount)
	}

	return discount, nil
}

func main() {
	// Example usage:
	order := map[string]interface{}{
		"total":    250.0,
		"isMember": true,
		"items":    5,
	}

	script := `
		var discount = 0;
		if (order.total > 200 && order.isMember) {
			discount = order.total * 0.15;
		} else if (order.total > 100) {
			discount = order.total * 0.05;
		}
		discount;
	`

	discount, err := CalculateDiscount(script, order)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return
	}
	fmt.Printf("Discount: %.2f\n", discount)
}

